class Component extends DCLogic {
 constructor(p){super(p);const roles=readRoleDirectory();this.state={roles,mobileDetail:false,query:'',showAll:false,archive:false,sel:roles[0]?.id||'',draft:roles[0]?{...roles[0]}:{},isNew:false,error:'',notice:'',archiveDialog:false};}
 select(r){this.setState({mobileDetail:true,sel:r.id,draft:{...r},isNew:false,error:'',notice:''});}
 save(){const s=this.state,d=s.draft;if(!d.title.trim()){this.setState({error:'Введите название роли.'});return;}if(roleDuplicate(s.roles,d.title,d.id)){this.setState({error:'Роль с таким названием уже есть, в том числе в архиве.'});return;}const role={...d,title:d.title.trim()};const roles=s.isNew?[...s.roles,role]:s.roles.map(r=>r.id===d.id?role:r);writeRoleDirectory(roles);this.setState({roles,sel:role.id,draft:role,isNew:false,error:'',notice:'Роль сохранена',archive:!!role.archived});}
 archive(value){const s=this.state;const roles=s.roles.map(r=>r.id===s.sel?{...r,archived:value}:r);writeRoleDirectory(roles);this.setState({roles,draft:{...s.draft,archived:value},archive:value,archiveDialog:false,notice:value?'Роль перемещена в архив':'Роль восстановлена'});}
 renderVals(){const s=this.state,d=s.draft;const change=k=>e=>this.setState({draft:{...this.state.draft,[k]:e.target.value},error:'',notice:''});const filtered=s.roles.filter(r=>!!r.archived===s.archive&&r.title.toLowerCase().includes(s.query.toLowerCase()));const usage=demoRead('schedule-v2',[{role:'assistant'},{role:'packing'},{role:'teacher'}]).filter(e=>e.role===d.id||Object.values(e.overrides||{}).some(o=>o.role===d.id)).length;return {
 workspaceClass:'r-workspace'+(s.mobileDetail?' is-detail':''),toolsClass:'r-tools'+(s.mobileDetail?' is-detail':''),back:()=>this.setState({mobileDetail:false}),query:s.query,search:e=>this.setState({query:e.target.value}),activeClass:s.archive?'':'is-on',archiveClass:s.archive?'is-on':'',showActive:()=>{const r=s.roles.find(r=>!r.archived);this.setState({archive:false,sel:r?.id||'',draft:r?{...r}:{},isNew:false,error:''});},showArchive:()=>{const r=s.roles.find(r=>r.archived);this.setState({archive:true,sel:r?.id||'',draft:r?{...r}:{},isNew:false,error:''});},hasMoreRoles:!s.showAll&&!s.query&&filtered.length>4,expandRoles:()=>this.setState({showAll:true}),moreRolesLabel:'Показать все '+filtered.length,roles:filtered.map((r,i)=>({...r,visible:s.showAll||!!s.query||i<4,cls:'row-button r-role'+(s.sel===r.id?' is-on':''),pressed:s.sel===r.id?'true':'false',prepLabel:r.prep||'Подготовка пока не указана',pick:()=>this.select(r)})),empty:!filtered.length,emptyLabel:s.query?'Ничего не найдено':s.archive?'Архив пуст':'Нет действующих ролей',clearSearch:()=>this.setState({query:''}),
 hasSelection:!!s.sel||s.isNew,noSelection:!s.sel&&!s.isNew,editorTitle:s.isNew?'Новая роль':'Редактирование роли',draft:d,changeTitle:change('title'),changeTask:change('task'),changePrep:change('prep'),toggleCertificate:()=>this.setState({draft:{...d,certificate:!d.certificate}}),toggleApproval:()=>this.setState({draft:{...d,approval:!d.approval}}),save:()=>this.save(),cancel:()=>{const r=s.roles.find(r=>r.id===s.sel)||s.roles.find(r=>!r.archived);if(r)this.select(r);else this.setState({isNew:false,draft:{},sel:''});},create:()=>this.setState({mobileDetail:true,isNew:true,sel:'',draft:{id:'role-'+Date.now(),title:'',task:'',prep:'',certificate:true,approval:true,archived:false},error:'',notice:''}),archived:!!d.archived,canArchive:!s.isNew&&!d.archived,askArchive:()=>this.setState({archiveDialog:true}),archiveDialog:s.archiveDialog,archive:()=>this.archive(true),keep:()=>this.setState({archiveDialog:false}),restore:()=>this.archive(false),archiveKey:e=>{if(e.key==='Escape')this.setState({archiveDialog:false});if(e.key==='Tab'){const buttons=Array.from(e.currentTarget.querySelectorAll('button'));if(e.shiftKey&&e.target===buttons[0]){e.preventDefault();buttons[buttons.length-1].focus();}else if(!e.shiftKey&&e.target===buttons[buttons.length-1]){e.preventDefault();buttons[0].focus();}}},error:s.error,notice:s.notice,usageLabel:usage?'Используется в расписании. Изменение роли не меняет договорённости по назначенным занятиям.':d.archived?'Роль в архиве. Восстановите её, чтобы снова выбирать для занятий.':'Можно выбрать при создании занятия.'
 };}
}
